\set ON_ERROR_STOP on
begin;
create temp table checks(label text);
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label; end if; insert into checks values(label); end$$;
create function pg_temp.denied(q text,code text,label text) returns void language plpgsql as $$begin begin execute q; exception when others then if sqlstate=code then perform pg_temp.ok(true,label); return; end if; raise; end; raise exception 'FAIL: % allowed',label; end$$;
do $$ declare
  u uuid:='bbbbbbbb-0000-0000-0000-000000000001'; a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); admin uuid:=gen_random_uuid();
  j uuid; j2 uuid; f uuid; f2 uuid; cat uuid; cf uuid; v2 uuid:=gen_random_uuid(); x jsonb; y jsonb; snapshot jsonb; events jsonb; e bigint; n integer; v_revision bigint; v_epochs jsonb; v_tasks jsonb; v_old timestamptz; v_def text;
begin
  perform pg_temp.ok(to_regprocedure('public.claim_whatsapp_automation(uuid)') is not null,'ledger RPC installed');
  insert into auth.users(id) values(admin); insert into public.platform_admins values(admin);
  insert into public.platform_flags(key,value) values('whatsapp_automation_dispatch','true'),('whatsapp_template_catalog','true') on conflict(key) do update set value=excluded.value;
  update public.whatsapp_channels set last_health_check_at=clock_timestamp() where id='dddddddd-0000-0000-0000-000000000001';
  insert into public.whatsapp_template_accounts(id,organization_id,waba_id,verified_at,binding_generation) values(a,'aaaaaaaa-0000-0000-0000-000000000001','2712345',clock_timestamp(),7);
  insert into public.whatsapp_template_bindings(id,unit_id,channel_id,account_id,provider,generation,verified_at) values(b,u,'dddddddd-0000-0000-0000-000000000001',a,'datafy',3,clock_timestamp());
  perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',admin)::text,true);
  update public.whatsapp_template_bindings set adopted_at=clock_timestamp(),dispatch_enabled=true,submission_authorized_at=clock_timestamp(),submission_authorized_by=admin where id=b;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  insert into public.whatsapp_remote_templates(id,account_id,logical_id,version,language,name,desired_hash,requested_category,binding_generation) values(t,a,'res_confirmacao_v1',1,'pt_BR','res_confirmacao_v1',repeat('a',64),'UTILITY',7);
  x:=public.begin_whatsapp_template_sync(a);
  snapshot:=jsonb_build_array(jsonb_build_object('id',t,'remote_id','remote27','name','res_confirmacao_v1','language','pt_BR','observed_hash',repeat('a',64),'effective_category','UTILITY','remote_status','APPROVED','quality','GREEN'));
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,snapshot),'GET publishes current account generation7, distinct binding3');
  perform pg_temp.ok(not public.publish_whatsapp_template_sync(a,3,x,snapshot),'binding generation is not account generation');
  perform pg_temp.ok(not public.publish_whatsapp_template_sync(a,7,x||jsonb_build_object('templates','[]'::jsonb),snapshot),'missing epoch refuses complete snapshot');
  perform pg_temp.ok(not public.publish_whatsapp_template_sync(a,7,x||jsonb_build_object('templates',(x->'templates')||(x->'templates')),snapshot),'duplicate epoch refuses snapshot');
  y:=jsonb_build_object('unit_id',u,'kind','confirmation','reservation_id','eeeeeeee-0000-0000-0000-000000000001','source_event_key','first','fact_at',clock_timestamp()+interval '1 hour','expires_at',clock_timestamp()+interval '1 hour');
  j:=public.enqueue_whatsapp_automation(y);
  perform pg_temp.ok(j is not null,'enqueue derives real org/customer/current binding');
  perform pg_temp.ok((select binding_generation=3 and account_id=a and customer_id='cccccccc-0000-0000-0000-000000000001' from public.whatsapp_automation_jobs where id=j),'pins derived customer and binding generation');
  -- Stored future versions do not authorize catalog rollout or replace v1.
  insert into public.whatsapp_remote_templates(id,account_id,logical_id,version,language,name,desired_hash,requested_category,binding_generation,remote_status,local_status)
    values(v2,a,'res_confirmacao_v1',2,'pt_BR','res_confirmacao_v2',repeat('f',64),'UTILITY',7,'PENDING','pending');
  insert into public.reservations(id,unit_id,customer_id) values('eeeeeeee-0000-0000-0000-000000000040',u,'cccccccc-0000-0000-0000-000000000001'),('eeeeeeee-0000-0000-0000-000000000041',u,'cccccccc-0000-0000-0000-000000000001');
  perform pg_temp.ok((select local_status='usable' from public.whatsapp_remote_templates where id=t),'v1 remains usable while v2 is pending');
  j2:=public.enqueue_whatsapp_automation(y||'{"reservation_id":"eeeeeeee-0000-0000-0000-000000000040"}');
  perform pg_temp.ok((select remote_template_id=t and template_version=1 from public.whatsapp_automation_jobs where id=j2),'pending v2 never replaces explicit v1 pt_BR');
  update public.whatsapp_remote_templates set remote_id='future27',remote_status='APPROVED',local_status='usable',observed_hash=desired_hash,effective_category=requested_category,sync_required=false,last_synced_at=clock_timestamp(),quality='GREEN' where id=v2;
  j2:=public.enqueue_whatsapp_automation(y||'{"reservation_id":"eeeeeeee-0000-0000-0000-000000000041"}');
  perform pg_temp.ok((select remote_template_id=t and template_version=1 from public.whatsapp_automation_jobs where id=j2),'approved usable v2 without rollout still pins v1');
  perform pg_temp.ok(public.enqueue_whatsapp_automation(y||'{"source_event_key":"future_version"}')=j,'future version leaves existing natural intent unchanged');
  perform pg_temp.ok((select remote_template_id=t and template_version=1 from public.whatsapp_automation_jobs where id=j),'existing pinned v1 unchanged');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set remote_template_id=%L,template_version=2 where id=%L',v2,j),'23514','existing pin cannot migrate to unrolled v2');
  delete from public.whatsapp_remote_templates where id=v2;
  update public.platform_flags set value='false' where key='whatsapp_automation_dispatch';
  perform pg_temp.ok(public.enqueue_whatsapp_automation(y||'{"source_event_key":"second"}')=j,'existing ledger wins flagsOFF/source change');
  update public.platform_flags set value='true' where key='whatsapp_automation_dispatch';
  perform pg_temp.denied(format('select public.enqueue_whatsapp_automation(%L::jsonb)',y||jsonb_build_object('unit_id','bbbbbbbb-0000-0000-0000-000000000003')),'42501','foreign resource refused');
  perform pg_temp.denied(format('select public.enqueue_whatsapp_automation(%L::jsonb)',y||jsonb_build_object('reservation_id',gen_random_uuid())),'42501','missing resource same refusal');
  perform pg_temp.denied(format('select public.enqueue_whatsapp_automation(%L::jsonb)',y||'{"customer_id":"cccccccc-0000-0000-0000-000000000001"}'),'22023','body customer is not authority');
  x:=public.claim_whatsapp_automation(j); f:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(f is not null and (x->>'attempts')::integer=0,'claim UUID does not consume POST attempt');
  perform pg_temp.ok(public.claim_whatsapp_automation(j) is null,'live claim cannot be stolen');
  update public.whatsapp_automation_jobs set safe_log_body='Safe render27' where id=j;
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j,gen_random_uuid(),3,null,e),'wrong prepare fence refuses');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,gen_random_uuid(),'{"outcome":"uncertain","reason":"post_ambiguous"}'),'wrong finish fence refuses');
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j,f,3,null,e),'ordered SQL preflight prepares approved snapshot');
  perform pg_temp.ok((select state='posting' and attempts=1 and posting_started_at is not null from public.whatsapp_automation_jobs where id=j),'actual POST start consumes one attempt');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set posting_started_at=null,state=''retry_wait'' where id=%L',j),'23514','service direct reset cannot manufacture retry');
  perform pg_temp.ok(public.finish_whatsapp_automation(j,f,'{"outcome":"rejected","reason":"documented_preproxy_429"}'),'documented Datafy preproxy rejection authorizes narrow reset');
  perform pg_temp.ok((select state='retry_wait' and posting_started_at is null and safe_log_body is null and attempts=1 and due_at>=clock_timestamp()+interval '59 seconds' from public.whatsapp_automation_jobs where id=j),'retry resets attempt render only, backoff retained');
  perform pg_temp.ok((select count(*)=0 from app_private.whatsapp_post_reset_permits),'one-use permit consumed');
  perform pg_temp.ok(public.claim_whatsapp_automation(j) is null,'retry not yet due');
  update public.whatsapp_automation_jobs set due_at=clock_timestamp()-interval '1 second' where id=j;
  x:=public.claim_whatsapp_automation(j); f2:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(f2<>f,'next attempt gets new fence');
  update public.whatsapp_automation_jobs set safe_log_body='Second safe render' where id=j;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j,f2,3,null,e),'retry prepare uses same pinned identity');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,f,'{"outcome":"accepted","reason":"provider_accepted","provider_message_id":"stale"}'),'stale earlier fence cannot accept');
  update public.whatsapp_automation_jobs set claimed_until=clock_timestamp()-interval '1 second' where id=j;
  perform pg_temp.ok(public.claim_whatsapp_automation(j) is null,'posting expiry never returns new ownership');
  perform pg_temp.ok((select state='uncertain' and claim_token=f2 and posting_started_at is not null from public.whatsapp_automation_jobs where id=j),'expired POST retains original fence');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,f2,'{"outcome":"rejected","reason":"documented_preproxy_429"}'),'uncertain cannot issue retry permit');
  perform pg_temp.ok(public.finish_whatsapp_automation(j,f2,'{"outcome":"accepted","reason":"provider_accepted","provider_message_id":"accepted27"}'),'late same-fence acceptance records evidence');
  perform pg_temp.denied(format('select public.finish_whatsapp_automation(%L,%L,''{"outcome":"accepted","reason":"provider_accepted","provider_message_id":123}'')',j,f2),'22023','numeric native ID not coerced into acceptance');
  perform pg_temp.ok(public.finish_whatsapp_automation(j,f2,'{"outcome":"accepted","reason":"provider_accepted","provider_message_id":"accepted27"}'),'identical accepted evidence idempotent');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,f2,'{"outcome":"accepted","reason":"provider_accepted","provider_message_id":"other"}'),'accepted ID cannot change');
  perform pg_temp.ok(not public.finish_whatsapp_automation(j,f2,'{"outcome":"uncertain","reason":"post_ambiguous"}'),'accepted cannot downgrade');
  perform pg_temp.ok((select reconcile_required and provider_message_id='accepted27' and attempts=2 from public.whatsapp_automation_jobs where id=j),'acceptance preserves evidence and local repair obligation');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set provider_message_id=null where id=%L',j),'23514','accepted ID direct clear denied');
  -- Events: positive invalidates, stale GET cannot release, RED survives omission.
  x:=public.begin_whatsapp_template_sync(a);
  events:=jsonb_build_array(jsonb_build_object('field','message_template_status_update','remote_id','remote27','event_time',clock_timestamp(),'digest',repeat('b',64),'remote_status','APPROVED'));
  perform pg_temp.ok(public.record_whatsapp_template_events(a,events)=1,'sanitized positive batch persisted');
  perform pg_temp.ok((select reconciliation_revision=1 from public.whatsapp_template_accounts where id=a),'new event increments task revision');
  perform pg_temp.ok(public.record_whatsapp_template_events(a,events)=0,'duplicate event coalesces');
  perform pg_temp.ok((select reconciliation_revision=1 from public.whatsapp_template_accounts where id=a),'dedupe does not increment task revision');
  perform pg_temp.ok(not public.publish_whatsapp_template_sync(a,7,x,snapshot),'callback invalidates in-flight GET epoch');
  perform pg_temp.ok((select sync_required from public.whatsapp_remote_templates where id=t),'positive callback never releases');
  select id into cat from public.whatsapp_template_jobs where account_id=a and operation='sync' and revision=1;
  y:=public.claim_whatsapp_template_job(cat); cf:=(y->>'claim_token')::uuid;
  perform pg_temp.ok(not public.finish_whatsapp_template_job(cat,cf,'{"outcome":"accepted","reason":"provider_accepted"}'),'generic acceptance cannot complete an unverified sync');
  perform pg_temp.ok(not public.complete_whatsapp_template_sync_job(cat,cf,true,'template_synced'),'sync_required prevents completion without current GET');
  x:=public.begin_whatsapp_template_sync(a);
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,snapshot),'sync task publishes current complete GET');
  perform pg_temp.ok(public.complete_whatsapp_template_sync_job(cat,cf,true,'template_synced'),'sync task completed without POST');
  delete from public.whatsapp_template_events where account_id=a and digest=repeat('b',64);
  events:=jsonb_build_array((events->0)||jsonb_build_object('digest',repeat('e',64)));
  perform pg_temp.ok(public.record_whatsapp_template_events(a,events)=1,'new event after purge persists');
  perform pg_temp.ok((select reconciliation_revision=2 from public.whatsapp_template_accounts where id=a),'purge never reuses task revision');
  perform pg_temp.ok(exists(select from public.whatsapp_template_jobs where account_id=a and operation='sync' and revision=2 and state='queued'),'new event queues new revision after prior sync done');
  perform pg_temp.denied(format('update public.whatsapp_template_accounts set reconciliation_revision=0 where id=%L',a),'23514','account task revision cannot regress');
  y:=jsonb_build_object('unit_id',u,'kind','confirmation','reservation_id','eeeeeeee-0000-0000-0000-000000000001','source_event_key','first','fact_at',clock_timestamp()+interval '1 hour','expires_at',clock_timestamp()+interval '1 hour');
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  select reconciliation_revision into v_revision from public.whatsapp_template_accounts where id=a;
  select jsonb_agg(jsonb_build_object('id',id,'epoch',sync_epoch,'sync_required',sync_required) order by id) into v_epochs from public.whatsapp_remote_templates where account_id=a;
  select coalesce(jsonb_agg(to_jsonb(tj) order by tj.id),'[]'::jsonb) into v_tasks from public.whatsapp_template_jobs tj where account_id=a;
  perform pg_temp.ok(not exists(select from public.whatsapp_template_events where account_id=a and digest=repeat('9',64)),'invalid batch first digest is new');
  perform pg_temp.denied(format('select public.record_whatsapp_template_events(%L,%L::jsonb)',a,jsonb_build_array((events->0)||jsonb_build_object('digest',repeat('9',64)),jsonb_build_object('field','unknown','remote_id','bad','event_time',clock_timestamp(),'digest',repeat('c',64)))),'23514','mixed invalid batch rolls back new first event');
  perform pg_temp.ok(not exists(select from public.whatsapp_template_events where account_id=a and digest=repeat('9',64)),'failed batch cannot persist first event');
  perform pg_temp.ok((select reconciliation_revision=v_revision from public.whatsapp_template_accounts where id=a),'failed batch cannot advance reconciliation revision');
  perform pg_temp.ok((select jsonb_agg(jsonb_build_object('id',id,'epoch',sync_epoch,'sync_required',sync_required) order by id)=v_epochs from public.whatsapp_remote_templates where account_id=a),'failed batch restores every epoch and sync requirement');
  perform pg_temp.ok((select coalesce(jsonb_agg(to_jsonb(tj) order by tj.id),'[]'::jsonb)=v_tasks from public.whatsapp_template_jobs tj where account_id=a),'failed batch cannot change task queue');
  perform pg_temp.ok((select sync_epoch=e from public.whatsapp_remote_templates where id=t),'failed batch cannot partially invalidate');
  events:=jsonb_build_array(jsonb_build_object('field','message_template_quality_update','remote_id','remote27','event_time',clock_timestamp(),'digest',repeat('d',64),'quality','RED'));
  perform public.record_whatsapp_template_events(a,events);
  x:=public.begin_whatsapp_template_sync(a);
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,jsonb_build_array((snapshot->0)-'quality')),'GET without quality publishes but preserves known RED');
  perform pg_temp.ok((select quality='RED' and local_status='usable' from public.whatsapp_remote_templates where id=t),'GET preserves RED metadata but UTILITY remains usable');
  insert into public.reservations(id,unit_id,customer_id) values('eeeeeeee-0000-0000-0000-000000000030',u,'cccccccc-0000-0000-0000-000000000001');
  j2:=public.enqueue_whatsapp_automation(y||'{"reservation_id":"eeeeeeee-0000-0000-0000-000000000030"}');
  x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='Approved UTILITY RED render' where id=j2;
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j2,f,3,null,e),'approved hash/category current GET UTILITY RED can POST');
  perform public.finish_whatsapp_automation(j2,f,'{"outcome":"uncertain","reason":"post_ambiguous"}');
  x:=public.begin_whatsapp_template_sync(a);
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,snapshot),'current explicit quality GET recovers');
  -- Prior notifications: exact FK, never failed/skipped/email/customer/day guessing.
  insert into public.reservations(id,unit_id,customer_id) values('eeeeeeee-0000-0000-0000-000000000027',u,'cccccccc-0000-0000-0000-000000000001');
  insert into public.notifications_sent(unit_id,reservation_id,kind,status) values(u,'eeeeeeee-0000-0000-0000-000000000027','confirmation','sent');
  y:=y||'{"reservation_id":"eeeeeeee-0000-0000-0000-000000000027"}';
  perform pg_temp.ok(public.enqueue_whatsapp_automation(y) is null,'accepted exact legacy resource prevents duplicate');
  update public.notifications_sent set status='failed' where reservation_id='eeeeeeee-0000-0000-0000-000000000027';
  update public.platform_flags set value='false' where key='whatsapp_automation_dispatch';
  perform pg_temp.denied(format('select public.enqueue_whatsapp_automation(%L::jsonb)',y),'P0A01','paused new intent is operational refusal, never NULL/fallback');
  update public.platform_flags set value='true' where key='whatsapp_automation_dispatch';
  j2:=public.enqueue_whatsapp_automation(y); perform pg_temp.ok(j2 is not null,'failed legacy notification is not accepted');
  x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='Safe27' where id=j2;
  update public.whatsapp_template_bindings set generation=4 where id=b;
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,3,null,e),'binding generation drift refuses');
  perform pg_temp.ok((select state='needs_review' and attempts=0 from public.whatsapp_automation_jobs where id=j2),'binding drift needs review, no POST attempt');
  perform pg_temp.ok(not public.requeue_whatsapp_automation(j2),'needs_review never automatic requeue');
  perform pg_temp.ok(not public.requeue_whatsapp_automation(j),'accepted never requeue');
  perform pg_temp.ok(not public.requeue_whatsapp_automation(gen_random_uuid()),'missing job requeue refused');
  insert into public.reservations(id,unit_id,customer_id) values('eeeeeeee-0000-0000-0000-000000000028',u,'cccccccc-0000-0000-0000-000000000001');
  y:=y||'{"reservation_id":"eeeeeeee-0000-0000-0000-000000000028"}';
  j2:=public.enqueue_whatsapp_automation(y); x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='Requeue snapshot' where id=j2;
  update public.platform_flags set value='false' where key='whatsapp_automation_dispatch';
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,4,null,e),'OFF pauses unposted claim');
  select expires_at into v_old from public.whatsapp_automation_jobs where id=j2;
  update public.platform_flags set value='true' where key='whatsapp_automation_dispatch';
  perform pg_temp.ok(public.requeue_whatsapp_automation(j2),'paused unposted explicit requeue');
  perform pg_temp.ok((select claim_token is null and claimed_until is null and attempts=0 and expires_at=v_old from public.whatsapp_automation_jobs where id=j2),'requeue clears only unposted lease, never deadline/attempts');
  x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  x:=public.begin_whatsapp_template_sync(a);
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,4,null,e),'sync-required blocks same logical job');
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,snapshot),'same template GET restores snapshot');
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  perform pg_temp.ok(public.requeue_whatsapp_automation(j2),'blocked same identity requeue');
  x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j2,f,4,null,e),'current epoch refresh recovers same natural key');
  perform pg_temp.ok((select sync_epoch=e from public.whatsapp_automation_jobs where id=j2),'POST pins recovered epoch');
  perform pg_temp.ok(not public.requeue_whatsapp_automation(j2),'posting marker never requeue');
  perform public.finish_whatsapp_automation(j2,f,'{"outcome":"uncertain","reason":"post_ambiguous"}');
  perform pg_temp.ok(not public.requeue_whatsapp_automation(j2),'uncertain never requeue');
  -- Nonofficial text still requires promotional protections; no permissive seam.
  insert into public.whatsapp_template_bindings(id,unit_id,channel_id,provider) values('27272727-0000-0000-0000-000000000001','bbbbbbbb-0000-0000-0000-000000000003','dddddddd-0000-0000-0000-000000000003','zapi');
  perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',admin)::text,true);
  update public.whatsapp_template_bindings set adopted_at=clock_timestamp(),dispatch_enabled=true where id='27272727-0000-0000-0000-000000000001';
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  update public.whatsapp_channels set last_health_check_at=clock_timestamp() where id='dddddddd-0000-0000-0000-000000000003';
  insert into public.waitlist(id,unit_id,customer_phone,customer_name,status) values('27272727-0000-0000-0000-000000000002','bbbbbbbb-0000-0000-0000-000000000003','11911110002','Fixture B','seated');
  y:=jsonb_build_object('unit_id','bbbbbbbb-0000-0000-0000-000000000003','kind','waitlist_feedback','waitlist_id','27272727-0000-0000-0000-000000000002','source_event_key','promotion','fact_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '1 hour');
  j2:=public.enqueue_whatsapp_automation(y); x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='Promotional redacted render' where id=j2;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,1,null,null),'text promotion fails closed without individual opt-in');
  perform pg_temp.ok((select state='blocked' and error_code='consent_changed' and attempts=0 from public.whatsapp_automation_jobs where id=j2),'unknown promotional consent no network attempt');
  perform pg_temp.ok((select customer_id='cccccccc-0000-0000-0000-000000000002' and account_id is null from public.whatsapp_automation_jobs where id=j2),'nullable waitlist ID resolves phone in actual org, no fake account');
  insert into public.customers(id,organization_id,name,phone) values('27272727-0000-0000-0000-000000000003','aaaaaaaa-0000-0000-0000-000000000002','Changed recipient','11911110029');
  update public.waitlist set customer_phone='11911110029' where id='27272727-0000-0000-0000-000000000002';
  perform pg_temp.ok(public.requeue_whatsapp_automation(j2),'requeue only reevaluates blockers');
  x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,1,null,null),'recipient drift is never automatic transfer');
  perform pg_temp.ok((select state='needs_review' and customer_id='cccccccc-0000-0000-0000-000000000002' from public.whatsapp_automation_jobs where id=j2),'recipient pin preserved in needs_review');
  insert into public.waitlist(id,unit_id,customer_phone) values('27272727-0000-0000-0000-000000000004','bbbbbbbb-0000-0000-0000-000000000003','11911110002');
  v_old:=clock_timestamp()-interval '1 hour';
  y:=y||jsonb_build_object('kind','waitlist_entered','waitlist_id','27272727-0000-0000-0000-000000000004','fact_at',v_old,'expires_at',v_old);
  j2:=public.enqueue_whatsapp_automation(y);
  perform pg_temp.ok((select expires_at=fact_at from public.whatsapp_automation_jobs where id=j2),'SQL supports equality without duplicating TTL policy');
  update public.whatsapp_automation_jobs set state='blocked' where id=j2;
  perform pg_temp.ok(not public.requeue_whatsapp_automation(j2),'expired original deadline never requeue');
  update public.whatsapp_automation_jobs set state='queued' where id=j2;
  perform pg_temp.ok(public.claim_whatsapp_automation(j2) is null,'expired job cannot gain possession');
  perform pg_temp.ok((select state='expired' and posting_started_at is null from public.whatsapp_automation_jobs where id=j2),'expired job terminal without POST');
  perform pg_temp.denied(format('update public.whatsapp_automation_jobs set expires_at=expires_at+interval ''1 day'' where id=%L',j2),'23514','deadline cannot renew on retry');
  for n in 1..25 loop
    insert into public.waitlist(id,unit_id,customer_phone) values(gen_random_uuid(),'bbbbbbbb-0000-0000-0000-000000000003','11911110002') returning id into j2;
    perform public.enqueue_whatsapp_automation(y||jsonb_build_object('waitlist_id',j2,'fact_at',clock_timestamp(),'expires_at',clock_timestamp()+interval '1 hour'));
  end loop;
  perform pg_temp.ok((select count(*)=20 from public.select_due_whatsapp_automations(500)),'selection hard maximum20');
  perform pg_temp.ok((select count(*)=0 from public.select_due_whatsapp_automations(-1)),'negative selection no batch');
  perform pg_temp.ok((select count(*)>=25 from public.whatsapp_automation_jobs where state='queued' and claim_token is null),'select does not claim batch');
  -- Positive mutation control: removing the natural-key unique index makes the
  -- duplicate-protection assertion fail. Intentional exception rolls DDL back.
  begin
    drop index public.whatsapp_automation_jobs_waitlist_idx;
    insert into public.whatsapp_automation_jobs select (jsonb_populate_record(null::public.whatsapp_automation_jobs,to_jsonb(jj)||jsonb_build_object('id',gen_random_uuid(),'notification_id',gen_random_uuid()))).* from public.whatsapp_automation_jobs jj where jj.waitlist_id=j2;
    perform pg_temp.ok((select count(*)=1 from public.whatsapp_automation_jobs where waitlist_id=j2),'CONTROL natural key');
    raise exception 'CONTROL unique mutation survived';
  exception when raise_exception then
    if sqlerrm not like 'FAIL: CONTROL natural key%' then raise; end if;
  end;
  perform pg_temp.ok(to_regclass('public.whatsapp_automation_jobs_waitlist_idx') is not null,'positive unique control caught and rolled back');
  select id into j2 from public.whatsapp_automation_jobs where waitlist_id=j2;
  x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='Fence control safe render' where id=j2;
  begin
    select pg_get_functiondef('public.prepare_whatsapp_automation_post(uuid,uuid,bigint,bigint,bigint)'::regprocedure) into v_def;
    execute replace(replace(v_def,'j.claim_token is distinct from p_fence or ','false or '),' and claim_token=p_fence','');
    perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,gen_random_uuid(),1,null,null),'CONTROL wrong fence');
    raise exception 'CONTROL fence mutation survived';
  exception when raise_exception then
    if sqlerrm not like 'FAIL: CONTROL wrong fence%' then raise; end if;
  end;
  perform pg_temp.ok((select state='claimed' and claim_token=f and posting_started_at is null from public.whatsapp_automation_jobs where id=j2),'positive fence control caught and rolled back');
  update public.whatsapp_automation_jobs set claimed_until=clock_timestamp()+interval '50 milliseconds' where id=j2;
  perform pg_sleep(0.1);
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,1,null,null),'actual SQL wallclock rejects expired lease');
  begin
    select pg_get_functiondef('public.prepare_whatsapp_automation_post(uuid,uuid,bigint,bigint,bigint)'::regprocedure) into v_def;
    execute replace(v_def,'clock_timestamp()','now()');
    perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,1,null,null),'CONTROL frozen transaction clock');
    raise exception 'CONTROL clock mutation survived';
  exception when raise_exception then
    if sqlerrm not like 'FAIL: CONTROL frozen transaction clock%' then raise; end if;
  end;
  perform pg_temp.ok((select posting_started_at is null and attempts=0 from public.whatsapp_automation_jobs where id=j2),'positive frozen-clock control caught and rolled back');
  x:=public.claim_whatsapp_automation(j2); f2:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(f2 is not null and f2<>f,'expired unposted claim safely gets new fence');
  update public.customers set do_not_contact=true where id='cccccccc-0000-0000-0000-000000000002';
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f2,1,null,null),'DNC after enqueue blocks operational text');
  perform pg_temp.ok((select error_code='do_not_contact' and attempts=0 from public.whatsapp_automation_jobs where id=j2),'DNC no attempt consumed');
  update public.customers set do_not_contact=false where id='cccccccc-0000-0000-0000-000000000002';
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values('bbbbbbbb-0000-0000-0000-000000000003','cccccccc-0000-0000-0000-000000000002','operational','opt_out','fixture','fixture27',clock_timestamp());
  perform public.requeue_whatsapp_automation(j2); x:=public.claim_whatsapp_automation(j2); f2:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f2,1,1,null),'current operational opt-out blocks even matching revision');
  insert into public.whatsapp_message_consent_events(unit_id,customer_id,purpose,decision,source_code,evidence_reference,observed_at) values('bbbbbbbb-0000-0000-0000-000000000003','cccccccc-0000-0000-0000-000000000002','operational','opt_in','fixture','fixture27',clock_timestamp());
  perform public.requeue_whatsapp_automation(j2); x:=public.claim_whatsapp_automation(j2); f2:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f2,1,1,null),'stale operational revision blocks');
  perform public.requeue_whatsapp_automation(j2); x:=public.claim_whatsapp_automation(j2); f2:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(public.prepare_whatsapp_automation_post(j2,f2,1,2,null),'current operational revision allows live text POST');
  -- Catalog POST claim/fence and rejection reset are equally strict.
  declare ca uuid:=gen_random_uuid(); cb uuid:=gen_random_uuid(); cc uuid:=gen_random_uuid(); ct uuid:=gen_random_uuid(); ct2 uuid:=gen_random_uuid(); cs jsonb;
  begin
  insert into public.whatsapp_channels(id,unit_id,provider,status,is_active,credentials,last_health_check_at)
    values(cc,u,'datafy','connected',false,'{"phone_number_id":"2701"}',clock_timestamp());
  insert into public.whatsapp_template_accounts(id,organization_id,waba_id,verified_at,binding_generation)
    values(ca,'aaaaaaaa-0000-0000-0000-000000000001','279999',clock_timestamp(),1);
  insert into public.whatsapp_template_bindings(id,unit_id,channel_id,account_id,provider,generation,verified_at)
    values(cb,u,cc,ca,'datafy',4,clock_timestamp());
  perform set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',admin)::text,true);
  update public.whatsapp_template_bindings set submission_authorized_at=clock_timestamp(),submission_authorized_by=admin where id=cb;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);
  insert into public.whatsapp_remote_templates(id,account_id,logical_id,version,language,name,desired_hash,requested_category,binding_generation)
    values(ct,ca,'res_confirmacao_v1',1,'pt_BR','res_confirmacao_v1',repeat('a',64),'UTILITY',1),
    (ct2,ca,'fila_entrada_v1',1,'pt_BR','fila_entrada_v1',repeat('b',64),'UTILITY',1);
  cs:=jsonb_build_array(jsonb_build_object('id',ct,'remote_id',null,'name','res_confirmacao_v1','language','pt_BR','observed_hash',null,'effective_category',null,'remote_status','UNKNOWN'),
    jsonb_build_object('id',ct2,'remote_id',null,'name','fila_entrada_v1','language','pt_BR','observed_hash',null,'effective_category',null,'remote_status','UNKNOWN'));
  x:=public.begin_whatsapp_template_sync(ca);
  perform pg_temp.ok(public.publish_whatsapp_template_sync(ca,1,x,cs),'catalog provisioning requires current complete GET');
  cat:=public.enqueue_whatsapp_template_job(cb,'provision','res_confirmacao_v1',1);
  perform pg_temp.ok(public.enqueue_whatsapp_template_job(cb,'provision','res_confirmacao_v1',1)=cat,'catalog natural key coalesces');
  x:=public.claim_whatsapp_template_job(cat); cf:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(not public.prepare_whatsapp_template_provision(cat,gen_random_uuid(),4),'catalog wrong fence refuses');
  perform pg_temp.ok(public.prepare_whatsapp_template_provision(cat,cf,4),'catalog prepares authorized provision');
  perform pg_temp.denied(format('update public.whatsapp_template_jobs set posting_started_at=null where id=%L',cat),'23514','catalog service direct reset denied');
  perform pg_temp.ok(public.finish_whatsapp_template_job(cat,cf,'{"outcome":"rejected","reason":"documented_preproxy_429"}'),'catalog documented rejection retry permit');
  perform pg_temp.ok((select posting_started_at is null and state='queued' and attempts=1 from public.whatsapp_template_jobs where id=cat),'catalog explicit rejection reset');
  update public.whatsapp_template_jobs set due_at=clock_timestamp()-interval '1 second' where id=cat;
  x:=public.claim_whatsapp_template_job(cat); cf:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(public.prepare_whatsapp_template_provision(cat,cf,4),'catalog second POST prepare');
  update public.whatsapp_template_jobs set claimed_until=clock_timestamp()-interval '1 second' where id=cat;
  perform pg_temp.ok(public.claim_whatsapp_template_job(cat) is null,'catalog posting cannot be reclaimed');
  perform pg_temp.ok((select state='uncertain' and claim_token=cf from public.whatsapp_template_jobs where id=cat),'catalog uncertain retains fence');
  perform pg_temp.ok(public.finish_whatsapp_template_job(cat,cf,'{"outcome":"accepted","reason":"provider_accepted"}'),'catalog late accepted same fence');
  cat:=public.enqueue_whatsapp_template_job(cb,'provision','fila_entrada_v1',1);
  update public.whatsapp_template_jobs set attempts=4 where id=cat;
  x:=public.claim_whatsapp_template_job(cat); cf:=(x->>'claim_token')::uuid;
  perform pg_temp.ok(public.prepare_whatsapp_template_provision(cat,cf,4),'fifth documented POST may prepare');
  perform pg_temp.ok(public.finish_whatsapp_template_job(cat,cf,'{"outcome":"rejected","reason":"documented_preproxy_429"}'),'fifth rejected attempt terminal');
  perform pg_temp.ok((select state='rejected' and attempts=5 and posting_started_at is not null from public.whatsapp_template_jobs where id=cat),'maxfive never resets marker for sixth POST');
  perform pg_temp.ok((select count(*)=0 from app_private.whatsapp_post_reset_permits),'all permits consumed');
  end;
  -- RED prevents MARKETING usability; fresh approved UTILITY is independent.
  insert into public.whatsapp_remote_templates(id,account_id,logical_id,version,language,name,desired_hash,requested_category,binding_generation) values(m,a,'mkt_voucher_programado_v1',1,'pt_BR','mkt_voucher_programado_v1',repeat('c',64),'MARKETING',7);
  snapshot:=jsonb_build_array((snapshot->0)||'{"quality":"RED"}',jsonb_build_object('id',m,'remote_id','marketing27','name','mkt_voucher_programado_v1','language','pt_BR','observed_hash',repeat('c',64),'effective_category','MARKETING','remote_status','APPROVED','quality','RED'));
  x:=public.begin_whatsapp_template_sync(a);
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,snapshot),'complete GET publishes both RED categories');
  perform pg_temp.ok((select quality='RED' and local_status='paused' from public.whatsapp_remote_templates where id=m),'MARKETING RED cannot be usable');
  perform pg_temp.ok((select quality='RED' and local_status='usable' from public.whatsapp_remote_templates where id=t),'UTILITY RED usable after valid GET');
  insert into public.reservations(id,unit_id,customer_id) values('eeeeeeee-0000-0000-0000-000000000031',u,'cccccccc-0000-0000-0000-000000000001');
  y:=jsonb_build_object('unit_id',u,'kind','confirmation','reservation_id','eeeeeeee-0000-0000-0000-000000000031','source_event_key','red_sync','fact_at',clock_timestamp()+interval '1 hour','expires_at',clock_timestamp()+interval '1 hour');
  j2:=public.enqueue_whatsapp_automation(y); x:=public.claim_whatsapp_automation(j2); f:=(x->>'claim_token')::uuid;
  update public.whatsapp_automation_jobs set safe_log_body='RED pending sync render' where id=j2;
  x:=public.begin_whatsapp_template_sync(a);
  select sync_epoch into e from public.whatsapp_remote_templates where id=t;
  perform pg_temp.ok(not public.prepare_whatsapp_automation_post(j2,f,4,null,e),'UTILITY RED plus sync-required refuses POST');
  perform pg_temp.ok((select count(*)=2 from public.whatsapp_remote_templates where account_id=a and quality='RED' and sync_required),'RED both categories require current GET');
  perform pg_temp.ok(public.publish_whatsapp_template_sync(a,7,x,jsonb_build_array((snapshot->0)-'quality',(snapshot->1)-'quality')),'GET omission preserves both RED metadata');
  perform pg_temp.ok((select quality='RED' and local_status<>'usable' from public.whatsapp_remote_templates where id=m),'MARKETING omission never clears RED blocker');
  -- Live role ACL assertions are complemented by real JWT/PostgREST integration.
  for x in select to_jsonb(p) from pg_proc p join pg_namespace ns on ns.oid=p.pronamespace where ns.nspname='public' and p.proname in('enqueue_whatsapp_automation','claim_whatsapp_automation','requeue_whatsapp_automation','prepare_whatsapp_automation_post','finish_whatsapp_automation','select_due_whatsapp_automations','enqueue_whatsapp_template_job','claim_whatsapp_template_job','prepare_whatsapp_template_provision','finish_whatsapp_template_job','begin_whatsapp_template_sync','publish_whatsapp_template_sync','record_whatsapp_template_events') loop
    perform pg_temp.ok(not has_function_privilege('anon',(x->>'oid')::oid,'EXECUTE'),'anon denied '||(x->>'proname'));
    perform pg_temp.ok(not has_function_privilege('authenticated',(x->>'oid')::oid,'EXECUTE'),'authenticated denied '||(x->>'proname'));
    perform pg_temp.ok(has_function_privilege('service_role',(x->>'oid')::oid,'EXECUTE'),'service granted '||(x->>'proname'));
  end loop;
end $$;
select count(*)||' claims assertions GREEN (rollback)' from checks;
rollback;
